import os, re, json
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo3_in = G['Demo pair 3 input']
demo3_out = G['Demo pair 3 output']
test_in = G['Test input']

print(f"Demo 3 Input: {len(demo3_in)}x{len(demo3_in[0])}")
print(f"Demo 3 Output: {len(demo3_out)}x{len(demo3_out[0])}")

# Find the separator row (all 9s)
sep_row_idx = -1
for r in range(len(demo3_in)):
    if all(demo3_in[r][c] == 9 for c in range(len(demo3_in[r]))):
        sep_row_idx = r
        break

print(f"\nSeparator row (all 9s) found at index: {sep_row_idx}")

# Check bottom section for patterns
print(f"\nBottom section (rows {sep_row_idx+1} to end):")
for r in range(sep_row_idx+1, len(demo3_in)):
    unique_vals = set(demo3_in[r])
    print(f"Row {r}: {unique_vals}")

# Check where 5 appears in bottom section
print("\nPositions of 5 in bottom section:")
for r in range(sep_row_idx+1, len(demo3_in)):
    for c in range(len(demo3_in[0])):
        if demo3_in[r][c] == 5:
            print(f"  ({r}, {c})")

# Now check output for 3s
print("\nPositions of 3 in output:")
for r in range(len(demo3_out)):
    for c in range(len(demo3_out[0])):
        if demo3_out[r][c] == 3:
            print(f"  ({r}, {c})")

demo3_in = G['Demo pair 3 input']
demo3_out = G['Demo pair 3 output']
sep_row_idx = 13

top_rows = len(demo3_in) // 2  # Should be roughly half
print(f"Top rows count: {top_rows}, Bottom rows count: {len(demo3_in) - sep_row_idx}")

# Check if output 3s correspond to positions where TOP has 4 AND BOTTOM has 5
print("\nChecking correlation: TOP(4) AND BOTTOM(5)")
matches = []
mismatches = []

for r_top in range(sep_row_idx):
    r_bottom_rel = r_top  # Direct row index offset from separator
    r_bottom_abs = sep_row_idx + 1 + r_top

    for c in range(len(demo3_in[0])):
        top_val = demo3_in[r_top][c]
        bot_val = demo3_in[r_bottom_abs][c]
        out_val = demo3_out[r_top][c]

        # When does output have 3?
        if out_val == 3:
            if top_val == 4 and bot_val == 5:
                matches.append((r_top, c))
            else:
                mismatches.append((r_top, c, top_val, bot_val, out_val))

print(f"\nPositions where OUT=3 and TOP=4, BOT=5: {len(matches)}")
if matches:
    print(f"Sample: {matches[:5]}")

print(f"\nMISMATCHES (OUT=3 but not TOP=4/BOT=5): {len(mismatches)}")
if mismatches:
    for m in mismatches[:10]:
        print(f"  Row {m[0]}, Col {m[1]}: TOP={m[2]}, BOT={m[3]} -> OUT=3")

# Also check reverse - when OUT=4
print("\n\nReverse check: OUT=4 means NOT(TOP=4 & BOT=5)?")
wrong_4s = []
for r_top in range(sep_row_idx):
    r_bottom_abs = sep_row_idx + 1 + r_top
    for c in range(len(demo3_in[0])):
        top_val = demo3_in[r_top][c]
        bot_val = demo3_in[r_bottom_abs][c]
        out_val = demo3_out[r_top][c]

        if out_val == 4:
            if top_val == 4 and bot_val == 5:
                wrong_4s.append((r_top, c, top_val, bot_val))

if wrong_4s:
    print(f"Found {len(wrong_4s)} cases where OUT=4 but TOP=4,BOT=5!")
    print(f"First few: {wrong_4s[:5]}")
else:
    print("CORRECT: All OUT=4 cases do NOT have TOP=4&BOT=5")

